import { verbWith } from './pure/interactPick'

export type { CarryEvent, CarryEventType, StationMode }

export type Supply = 'one item' | 'endless' | 'look only'

export interface PickupSpec {
  entity: Entity
  kind: string
  supply: Supply
  range: number
  pickVerb: string
  dropVerb: string
  throwVerb: string
  throwable: boolean
  heldScale: number
  returnSeconds: number
}

export interface StationSpec {
  entity: Entity
  mode: StationMode
  accepts: string
  turns: string
  combines: string
  seconds: number
  range: number
  itemHeight: number
  putVerb: string
  takeVerb: string
  workVerb: string
}

interface Pickup extends PickupSpec { id: string; name: string }
interface Station extends StationSpec { id: string; name: string }
interface Visual { sig: string; root: Entity; entities: Entity[]; flying: ItemRow | null }
interface Bar { root: Entity; back: Entity; fill: Entity; shown: number }
interface Extras { recipes: Record<string, Recipe>; combines: Record<string, string> }

interface CarryHub {
  pickups: Map<string, Pickup>
  stations: Map<string, Station>
  extras: Map<string, Extras>
  rules: CarryRules
  side: 'server' | 'client' | null
  state: CarryState
  view: CarryState | null
  seenRaw: unknown
  listeners: Set<(event: CarryEvent) => void>
  prediction: CarryPrediction | null
  visuals: Map<string, Visual>
  bars: Map<string, Bar>
  hidden: Map<Entity, boolean>
  lastSeen: Map<Player, Vec3>
}

const KEY = '__dclCarry_v1'
const STATE_KEY = 'carry'
const REQUEST = 'carry.act'
const EVENT = 'carry.event'
// the server sees positions ~10 times a second, so its range check is generous
const SLACK_M = 1.5
const HAND_OFFSET = { x: 0, y: 0, z: 0.1 }
const FLOOR_LIFT = 0.15
const DROP_AHEAD_M = 0.6
const THROW_M = 6
const BAR_WIDTH = 0.8
const EVENT_TYPES: CarryEventType[] = ['pick', 'drop', 'throw', 'put', 'take', 'combine', 'done', 'give', 'used', 'return']

function isHub(value: unknown): value is CarryHub {
  return typeof value === 'object' && value !== null && 'pickups' in value && value.pickups instanceof Map &&
    'stations' in value && value.stations instanceof Map && 'rules' in value && 'listeners' in value
}

function hub(): CarryHub {
  const globals = globalThis as unknown as Record<string, unknown>
  const current = globals[KEY]
  if (isHub(current)) return current
  const created: CarryHub = {
    pickups: new Map(), stations: new Map(), extras: new Map(), rules: { sources: {}, stations: {} },
    side: null, state: freshCarry(), view: null, seenRaw: undefined, listeners: new Set(), prediction: null,
    visuals: new Map(), bars: new Map(), hidden: new Map(), lastSeen: new Map()
  }
  globals[KEY] = created
  return created
}

type NameComponent = LastWriteWinElementSetComponentDefinition<{ value: string }>

function nameOf(entity: Entity): string {
  const names = (engine.getComponentOrNull('core-schema::Name') ??
    engine.defineComponent('core-schema::Name', { value: Schemas.String })) as NameComponent
  return names.getOrNull(entity)?.value.trim() ?? ''
}

const key = kindKey

function myAddress(): string {
  return PlayerIdentityData.getOrNull(engine.PlayerEntity)?.address.toLowerCase() ?? ''
}

function worldPosition(entity: Entity): Vec3 | null {
  return entityWorld(entity)?.position ?? null
}

// ---------------------------------------------------------------- registration

/** Called by the Pickup Item prefab from start(), on both sides. */
export function registerPickup(spec: PickupSpec): void {
  const h = hub()
  const name = nameOf(spec.entity)
  const id = key(name)
  if (id === '' || spec.kind.trim() === '') {
    reportProblem('Pickup Item', 'A Pickup Item needs a Name and a kind — give the entity a Name and set its kind.')
    return
  }
  if (h.pickups.has(id)) {
    reportProblem('Pickup Item', `Two Pickup Items are named "${name}" — give each its own Name.`)
    return
  }
  const pickup: Pickup = { ...spec, kind: spec.kind.trim(), id, name }
  h.pickups.set(id, pickup)
  if (spec.supply !== 'look only') {
    h.rules.sources[id] = { kind: pickup.kind, endless: spec.supply === 'endless', returnMs: Math.max(0, spec.returnSeconds) * 1000 }
  }
  start(h)
  if (h.side === 'client' && spec.supply === 'look only') setShown(h, spec.entity, false)
}

/** Called by the Work Station prefab from start(), on both sides. */
export function registerStation(spec: StationSpec): void {
  const h = hub()
  const name = nameOf(spec.entity)
  const id = key(name)
  if (id === '') {
    reportProblem('Work Station', 'A Work Station needs a Name — it is the id scripts use.')
    return
  }
  if (h.stations.has(id)) {
    reportProblem('Work Station', `Two Work Stations are named "${name}" — give each its own Name.`)
    return
  }
  h.stations.set(id, { ...spec, id, name })
  const extras = h.extras.get(id)
  const ms = Math.max(0.1, spec.seconds) * 1000
  h.rules.stations[id] = {
    mode: spec.mode,
    accepts: parseKinds(spec.accepts),
    recipes: { ...parseTurns(spec.turns, ms), ...extras?.recipes },
    combines: { ...parseCombines(spec.combines), ...extras?.combines }
  }
  start(h)
}

export function setRecipe(station: string, input: string, output: string, seconds: number): void {
  const h = hub()
  const id = key(station)
  const recipe = { out: output.trim(), ms: Math.max(0.1, seconds) * 1000 }
  const extras = h.extras.get(id) ?? { recipes: {}, combines: {} }
  extras.recipes[key(input)] = recipe
  h.extras.set(id, extras)
  const rule = h.rules.stations[id]
  if (rule !== undefined) rule.recipes[key(input)] = recipe
}

export function setCombine(station: string, a: string, b: string, output: string): void {
  const h = hub()
  const id = key(station)
  const extras = h.extras.get(id) ?? { recipes: {}, combines: {} }
  extras.combines[comboKey(a, b)] = output.trim()
  h.extras.set(id, extras)
  const rule = h.rules.stations[id]
  if (rule !== undefined) rule.combines[comboKey(a, b)] = output.trim()
}

function start(h: CarryHub): void {
  if (h.side !== null) return
  if (isServer()) {
    h.side = 'server'
    startServer(h)
  } else {
    h.side = 'client'
    startClient(h)
  }
}

// ---------------------------------------------------------------- reads (either side)

function current(h: CarryHub): CarryState {
  if (h.side === 'server') return h.state
  return h.view ?? readCarry(game.state[STATE_KEY])
}

export function heldBy(player: Player): { item: string; kind: string } | null {
  return heldItem(current(hub()), player.toLowerCase())
}

export function holderOf(item: string): Player | null {
  const row = current(hub()).items[key(item)]
  return row?.at === 'hand' && row.who !== undefined ? row.who : null
}

export function stationItem(station: string): { item: string; kind: string } | null {
  const state = current(hub())
  const item = state.stations[key(station)]?.item
  const row = item === undefined ? undefined : state.items[item]
  return item === undefined || row === undefined ? null : { item, kind: row.kind }
}

export function stationProgress(station: string): number {
  const h = hub()
  const id = key(station)
  const state = current(h)
  const row = state.stations[id]
  const onIt = row?.item === undefined ? undefined : state.items[row.item]
  const recipe = onIt === undefined ? null : recipeFor(h.rules.stations[id], onIt.kind)
  return recipe === null ? 0 : progressOf(row, recipe.ms, game.now())
}

export function onCarry(fn: (event: CarryEvent) => void): () => void {
  const h = hub()
  h.listeners.add(fn)
  return () => { h.listeners.delete(fn) }
}

export function onStation(station: string, fn: (event: CarryEvent) => void): () => void {
  const id = key(station)
  return onCarry((event) => { if (event.station !== undefined && key(event.station) === id) fn(event) })
}

// ---------------------------------------------------------------- server

function serverOnly(verb: string): CarryHub | null {
  const h = hub()
  if (!isServer()) {
    console.error(`[you] ${verb} only runs on the server. Put this line inside if (isServer()).`)
    return null
  }
  start(h)
  return h
}

function commit(h: CarryHub, result: CarryResult): boolean {
  if (!result.accepted) return false
  h.state = result.state
  publish(h)
  emit(h, result.events)
  return true
}

export function giveItem(player: Player, kind: string): boolean {
  const h = serverOnly('giveItem')
  return h !== null && kind.trim() !== '' && commit(h, giveCarry(h.state, player.toLowerCase(), kind.trim()))
}

export function takeItem(player: Player): string | null {
  const h = serverOnly('takeItem')
  if (h === null) return null
  const held = heldItem(h.state, player.toLowerCase())
  return held !== null && commit(h, useHeld(h.state, player.toLowerCase(), h.rules, game.now())) ? held.kind : null
}

export function putOnStation(station: string, kind: string | null): boolean {
  const h = serverOnly('putOnStation')
  return h !== null && commit(h, setStationKind(h.state, key(station), kind === null ? null : kind.trim(), h.rules, game.now()))
}

export function takeFromStation(station: string): string | null {
  const h = serverOnly('takeFromStation')
  if (h === null) return null
  const kind = stationItem(station)?.kind ?? null
  return kind !== null && commit(h, setStationKind(h.state, key(station), null, h.rules, game.now())) ? kind : null
}

function publish(h: CarryHub): void {
  game.setState({ [STATE_KEY]: h.state })
}

function named(h: CarryHub, event: CarryEvent): CarryEvent {
  if (event.station === undefined) return event
  return { ...event, station: h.stations.get(event.station)?.name ?? event.station }
}

function tell(h: CarryHub, event: CarryEvent): void {
  for (const listener of [...h.listeners]) {
    try {
      listener(event)
    } catch (e) {
      console.error(`[carry] an onCarry listener failed on "${event.type}":`, e)
    }
  }
}

function emit(h: CarryHub, events: CarryEvent[]): void {
  for (const raw of events) {
    const event = named(h, raw)
    tell(h, event)
    game.broadcast(EVENT, event)
  }
}

function near(player: Player, at: Vec3, range: number): boolean {
  const position = game.positionOf(player)
  if (position === null) return true
  return Math.hypot(position.x - at.x, position.z - at.z) <= range + SLACK_M
}

function stationNear(h: CarryHub, player: Player, station: string): boolean {
  const spec = h.stations.get(station)
  const at = spec === undefined ? null : worldPosition(spec.entity)
  return spec === undefined || at === null || near(player, at, spec.range)
}

function target(h: CarryHub, action: CarryAction): { at: Vec3; range: number } | null {
  if (action.type === 'pick') {
    const row = h.state.items[action.item]
    const pickup = h.pickups.get(action.item)
    if (row?.at === 'floor' && row.pos !== undefined) return { at: row.pos, range: pickup?.range ?? 2 }
    const at = pickup === undefined ? null : worldPosition(pickup.entity)
    return pickup === undefined || at === null ? null : { at, range: pickup.range }
  }
  if (action.type === 'put' || action.type === 'take' || (action.type === 'work' && action.on)) {
    const spec = h.stations.get(action.station)
    const at = spec === undefined ? null : worldPosition(spec.entity)
    return spec === undefined || at === null ? null : { at, range: spec.range }
  }
  return null
}

function serverAct(h: CarryHub, data: unknown, player: Player): { ok: boolean; message?: string } {
  let action = readAction(data)
  if (action === null) return { ok: false }
  const goal = target(h, action)
  if (goal !== null && !near(player, goal.at, goal.range)) return { ok: false, message: 'Move closer' }
  const feet = game.positionOf(player)
  if (action.type === 'drop' && feet !== null && Math.hypot(action.pos.x - feet.x, action.pos.z - feet.z) > 3) {
    action = { type: 'drop', pos: feet }
  }
  if (action.type === 'throw') action = { type: 'throw', from: action.from, to: clampThrow(action.from, action.to) }
  const result = applyCarry(h.state, action, player, h.rules, game.now())
  return commit(h, result) ? { ok: true } : { ok: false, message: result.message }
}

function serverTick(h: CarryHub): void {
  for (const row of Object.values(h.state.items)) {
    if (row.at !== 'hand' || row.who === undefined) continue
    const at = game.positionOf(row.who)
    if (at !== null) h.lastSeen.set(row.who, at)
  }
  const result = tickCarry(h.state, h.rules, game.now(), (player, station) => stationNear(h, player, station))
  if (!result.changed) return
  h.state = result.state
  publish(h)
  emit(h, result.events)
}

function startServer(h: CarryHub): void {
  game.onReady(() => publish(h))
  game.onRequest(REQUEST, (data: unknown, player) => serverAct(h, data, player))
  game.onPlayerLeave((player) => {
    h.state = leaveCarry(h.state, player, h.lastSeen.get(player) ?? null, game.now())
    h.lastSeen.delete(player)
    publish(h)
  })
  game.onRoundStart(() => {
    h.state = freshCarry(h.state.n)
    publish(h)
  })
  game.every(0.1, () => serverTick(h))
}

// ---------------------------------------------------------------- client

function readEvent(data: unknown): CarryEvent | null {
  if (typeof data !== 'object' || data === null) return null
  const raw = data as Record<string, unknown>
  if (!EVENT_TYPES.includes(raw.type as CarryEventType) || typeof raw.item !== 'string' || typeof raw.kind !== 'string') return null
  const event: CarryEvent = { type: raw.type as CarryEventType, item: raw.item, kind: raw.kind }
  if (typeof raw.player === 'string') event.player = raw.player
  if (typeof raw.station === 'string') event.station = raw.station
  if (typeof raw.was === 'string') event.was = raw.was
  return event
}

function replyOk(reply: unknown): { ok: boolean; message: string } {
  if (typeof reply !== 'object' || reply === null) return { ok: false, message: '' }
  const raw = reply as Record<string, unknown>
  return { ok: raw.ok === true, message: typeof raw.message === 'string' ? raw.message : '' }
}

function act(h: CarryHub, action: CarryAction): void {
  const prediction = h.prediction
  if (prediction === null) return
  const predicted = prediction.predict(action, game.now())
  if (predicted.id === null) {
    if (predicted.message !== '') sayNotice(predicted.message)
    return
  }
  const id = predicted.id
  game.request<unknown>(REQUEST, action).then((reply) => {
    const answer = replyOk(reply)
    if (answer.ok) return
    prediction.reject(id)
    if (answer.message !== '') sayNotice(answer.message)
  }, (error: unknown) => {
    prediction.reject(id)
    sayNotice('No answer from the server. Try again.')
    console.log(`[carry] ${action.type} failed: ${String(error)}`)
  })
}

function kindSpec(h: CarryHub, kind: string): Pickup | null {
  const wanted = key(kind)
  for (const pickup of h.pickups.values()) if (key(pickup.kind) === wanted) return pickup
  return null
}

function facing() {
  const rotation = Transform.getOrNull(engine.CameraEntity)?.rotation ?? Transform.getOrNull(engine.PlayerEntity)?.rotation ?? Quaternion.Identity()
  const forward = Vector3.rotate(Vector3.Forward(), rotation)
  const flat = Vector3.create(forward.x, 0, forward.z)
  return Vector3.length(flat) < 0.01 ? Vector3.Forward() : Vector3.normalize(flat)
}

function heldActions(h: CarryHub, kind: string): PromptAction[] {
  const spec = kindSpec(h, kind)
  const actions: PromptAction[] = [{
    verb: verbWith(spec?.dropVerb ?? 'Drop', ''), button: 'primary', run: (pressed) => {
      const feet = localPlayerPosition()
      if (!pressed || feet === null) return
      const ahead = Vector3.add(feet, Vector3.scale(facing(), DROP_AHEAD_M))
      act(h, { type: 'drop', pos: { x: ahead.x, y: feet.y, z: ahead.z } })
    }
  }]
  if (spec?.throwable === true) {
    actions.push({
      verb: verbWith(spec.throwVerb, ''), button: 'secondary', run: (pressed) => {
        const feet = localPlayerPosition()
        if (!pressed || feet === null) return
        const to = Vector3.add(feet, Vector3.scale(facing(), THROW_M))
        act(h, { type: 'throw', from: { x: feet.x, y: feet.y + 1.2, z: feet.z }, to: { x: to.x, y: feet.y, z: to.z } })
      }
    })
  }
  return actions
}

function candidates(h: CarryHub): PromptCandidate[] {
  const view = h.view
  const me = myAddress()
  if (view === null || me === '') return []
  const now = game.now()
  const mine = heldItem(view, me)
  const out: PromptCandidate[] = []
  if (mine === null) {
    for (const pickup of h.pickups.values()) {
      if (pickup.supply === 'look only' || (pickup.supply === 'one item' && view.items[pickup.id] !== undefined)) continue
      const at = worldPosition(pickup.entity)
      if (at === null) continue
      out.push({ key: `source:${pickup.id}`, position: at, range: pickup.range, actions: [{
        verb: verbWith(pickup.pickVerb, pickup.kind), button: 'primary',
        run: (pressed) => { if (pressed) act(h, { type: 'pick', item: pickup.id }) }
      }] })
    }
    for (const [item, row] of Object.entries(view.items)) {
      if (row.at !== 'floor') continue
      const at = flightPosition(row, now)
      const spec = kindSpec(h, row.kind)
      out.push({ key: `item:${item}`, position: at, range: spec?.range ?? 2, actions: [{
        verb: verbWith(spec?.pickVerb ?? 'Pick up', row.kind), button: 'primary',
        run: (pressed) => { if (pressed) act(h, { type: 'pick', item }) }
      }] })
    }
  }
  for (const station of h.stations.values()) {
    const rule = h.rules.stations[station.id]
    const row = view.stations[station.id]
    const onIt = row?.item === undefined ? undefined : view.items[row.item]
    const actions: PromptAction[] = []
    if (mine !== null) {
      const fits = onIt === undefined
        ? rule.accepts.length === 0 || rule.accepts.includes(key(mine.kind))
        : rule.combines[comboKey(onIt.kind, mine.kind)] !== undefined
      if (fits) actions.push({ verb: verbWith(station.putVerb, mine.kind), button: 'primary', run: (pressed) => { if (pressed) act(h, { type: 'put', station: station.id }) } })
    } else if (onIt !== undefined) {
      actions.push({ verb: verbWith(station.takeVerb, onIt.kind), button: 'primary', run: (pressed) => { if (pressed) act(h, { type: 'take', station: station.id }) } })
    }
    if (rule.mode === 'hold' && onIt !== undefined && recipeFor(rule, onIt.kind) !== null && (row?.by === undefined || row.by === me)) {
      actions.push({ verb: verbWith(station.workVerb, onIt.kind), button: 'secondary', hold: true,
        run: (pressed) => act(h, { type: 'work', station: station.id, on: pressed }) })
    }
    out.push({ key: `station:${station.id}`, position: worldPosition(station.entity), range: station.range,
      height: station.itemHeight + 0.7, actions })
  }
  if (mine !== null) out.push({ key: 'held', position: null, actions: heldActions(h, mine.kind) })
  return out
}

function setShown(h: CarryHub, entity: Entity, shown: boolean): void {
  if (h.hidden.get(entity) === !shown) return
  h.hidden.set(entity, !shown)
  VisibilityComponent.createOrReplace(entity, { visible: shown, propagateToChildren: true })
}

function template(h: CarryHub, kind: string): Entity | null {
  return kindSpec(h, kind)?.entity ?? null
}

function copyVisual(from: Entity, to: Entity): void {
  const gltf = GltfContainer.getOrNull(from)
  if (gltf !== null) GltfContainer.createOrReplace(to, { src: gltf.src, visibleMeshesCollisionMask: 0, invisibleMeshesCollisionMask: 0 })
  const mesh = MeshRenderer.getOrNull(from)
  if (mesh !== null) MeshRenderer.createOrReplace(to, JSON.parse(JSON.stringify(mesh)) as PBMeshRenderer)
  const material = Material.getOrNull(from)
  if (material !== null) Material.createOrReplace(to, JSON.parse(JSON.stringify(material)) as PBMaterial)
}

function copyChildren(from: Entity, to: Entity, out: Entity[], depth: number): void {
  if (depth > 3) return
  for (const [child, transform] of engine.getEntitiesWith(Transform)) {
    if (transform.parent !== from) continue
    const copy = engine.addEntity()
    out.push(copy)
    Transform.create(copy, { position: transform.position, rotation: transform.rotation, scale: transform.scale, parent: to })
    copyVisual(child, copy)
    copyChildren(child, copy, out, depth + 1)
  }
}

// What a kind looks like is its Pickup Item's own model (and its children's), copied — never the item itself,
// so a hand, a station and the floor can each show one.
function copyLook(h: CarryHub, kind: string, parent: Entity | undefined, position: Vec3, scale: number): Visual {
  const root = engine.addEntity()
  const entities = [root]
  const source = template(h, kind)
  const authored = source === null ? null : Transform.getOrNull(source)
  const base = authored?.scale ?? Vector3.create(0.3, 0.3, 0.3)
  Transform.create(root, { position, rotation: authored?.rotation ?? Quaternion.Identity(), scale: Vector3.scale(base, scale), parent })
  if (source === null) MeshRenderer.setBox(root)
  else {
    copyVisual(source, root)
    copyChildren(source, root, entities, 0)
  }
  return { sig: '', root, entities, flying: null }
}

function signature(row: ItemRow): string {
  const at = row.pos === undefined ? '' : `${row.pos.x},${row.pos.y},${row.pos.z}`
  return `${row.kind}|${row.at}|${row.who ?? ''}|${row.station ?? ''}|${at}|${row.t ?? ''}`
}

function lifted(at: Vec3): Vec3 {
  return { x: at.x, y: at.y + FLOOR_LIFT, z: at.z }
}

function createVisual(h: CarryHub, row: ItemRow, now: number): Visual | null {
  if (row.at === 'hand' && row.who !== undefined) {
    const anchor = engine.addEntity()
    Transform.create(anchor, {})
    AvatarAttach.create(anchor, {
      avatarId: row.who === myAddress() ? undefined : row.who,
      anchorPointId: AvatarAnchorPointType.AAPT_RIGHT_HAND
    })
    const look = copyLook(h, row.kind, anchor, HAND_OFFSET, kindSpec(h, row.kind)?.heldScale ?? 1)
    return { ...look, root: anchor, entities: [anchor, ...look.entities] }
  }
  if (row.at === 'station' && row.station !== undefined) {
    const station = h.stations.get(row.station)
    const at = station === undefined ? null : worldPosition(station.entity)
    if (station === undefined || at === null) return null
    return copyLook(h, row.kind, undefined, { x: at.x, y: at.y + station.itemHeight, z: at.z }, 1)
  }
  if (row.at === 'floor') {
    const at = flightPosition(row, now)
    if (at === null) return null
    const look = copyLook(h, row.kind, undefined, lifted(at), 1)
    return { ...look, flying: row.from !== undefined ? row : null }
  }
  return null
}

function removeVisual(visual: Visual): void {
  for (const entity of visual.entities) engine.removeEntity(entity)
}

function drawItems(h: CarryHub, view: CarryState, now: number): void {
  const seen = new Set<string>()
  for (const [item, row] of Object.entries(view.items)) {
    if (row.at === 'gone') continue
    const sig = signature(row)
    let visual = h.visuals.get(item)
    if (visual !== undefined && visual.sig !== sig) {
      removeVisual(visual)
      visual = undefined
    }
    if (visual === undefined) {
      const created = createVisual(h, row, now)
      if (created === null) continue
      visual = { ...created, sig }
      h.visuals.set(item, visual)
    }
    seen.add(item)
    const flying = visual.flying
    if (flying !== null && flying.t !== undefined) {
      const at = flightPosition(flying, now)
      if (at !== null) Transform.getMutable(visual.root).position = lifted(at)
      if (now - flying.t > THROW_MS) visual.flying = null
    }
  }
  for (const [item, visual] of [...h.visuals]) {
    if (seen.has(item)) continue
    removeVisual(visual)
    h.visuals.delete(item)
  }
  for (const pickup of h.pickups.values()) {
    if (pickup.supply === 'one item') setShown(h, pickup.entity, view.items[pickup.id] === undefined)
  }
}

function drawBars(h: CarryHub, view: CarryState, now: number): void {
  for (const station of h.stations.values()) {
    const row = view.stations[station.id]
    const onIt = row?.item === undefined ? undefined : view.items[row.item]
    const recipe = onIt === undefined ? null : recipeFor(h.rules.stations[station.id], onIt.kind)
    const working = row !== undefined && recipe !== null && (row.since !== undefined || row.work > 0)
    const bar = h.bars.get(station.id)
    if (!working) {
      if (bar !== undefined) {
        for (const entity of [bar.fill, bar.back, bar.root]) engine.removeEntity(entity)
        h.bars.delete(station.id)
      }
      continue
    }
    const progress = progressOf(row, recipe.ms, now)
    const shown = bar ?? createBar(h, station)
    if (shown === null || Math.abs(shown.shown - progress) < 0.005) continue
    shown.shown = progress
    const width = Math.max(0.001, (BAR_WIDTH - 0.04) * progress)
    Transform.createOrReplace(shown.fill, {
      parent: shown.root,
      position: { x: -(BAR_WIDTH - 0.04 - width) / 2, y: 0, z: 0 },
      scale: { x: width, y: 0.08, z: 0.03 }
    })
  }
}

function createBar(h: CarryHub, station: Station): Bar | null {
  const at = worldPosition(station.entity)
  if (at === null) return null
  const root = engine.addEntity()
  Transform.create(root, { position: { x: at.x, y: at.y + station.itemHeight + 0.5, z: at.z } })
  Billboard.create(root, { billboardMode: BillboardMode.BM_Y })
  const back = engine.addEntity()
  Transform.create(back, { parent: root, scale: { x: BAR_WIDTH, y: 0.12, z: 0.02 } })
  MeshRenderer.setBox(back)
  Material.setPbrMaterial(back, { albedoColor: Color4.create(0.1, 0.1, 0.12, 1) })
  const fill = engine.addEntity()
  MeshRenderer.setBox(fill)
  Material.setPbrMaterial(fill, { albedoColor: Color4.create(1, 0.77, 0.35, 1), emissiveColor: { r: 1, g: 0.6, b: 0.2 }, emissiveIntensity: 0.6 })
  const bar: Bar = { root, back, fill, shown: -1 }
  h.bars.set(station.id, bar)
  return bar
}

function clientTick(h: CarryHub): void {
  const prediction = h.prediction
  if (prediction === null) return
  const now = game.now()
  const raw = game.state[STATE_KEY]
  if (raw !== h.seenRaw || prediction.pendingCount > 0) {
    h.seenRaw = raw
    prediction.reconcile(readCarry(raw), now)
  }
  const view = prediction.view(now) ?? readCarry(raw)
  h.view = view
  drawItems(h, view, now)
  drawBars(h, view, now)
}

function startClient(h: CarryHub): void {
  h.prediction = new CarryPrediction(() => h.rules, myAddress)
  game.onBroadcast(EVENT, (data: unknown) => {
    const event = readEvent(data)
    if (event !== null) tell(h, event)
  })
  addInteractions(() => candidates(h))
  engine.addSystem(() => clientTick(h), undefined, 'runtime-carry')
}
